// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockNumber, uint256 timestamp) public {
        vm.assume(blockNumber > 0);
        vm.assume(blockNumber < type(uint256).max);
        vm.assume(timestamp > 0);
        vm.assume(timestamp < type(uint256).max);

        vm.roll(blockNumber);
        vm.warp(timestamp);

        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "fallback call failed");

        uint256 balanceAfter = address(c).balance;
        assertTrue(blockNumber % 15 != 0 || balanceAfter == 0);
    }
}
